  "about_items": [
    {
      "n": "#7·33",
      "text": "This is a grey ribbed turtleneck sweater with a fitted silhouette. Its fine vertical texture adds depth without being loud, and the high collar frames your neck beautifully."
    },
    {
      "n": "#48·37",
      "text": "These are wide-legged jeans in a light silvery wash featuring an all-over tonal logo print. They offer a relaxed yet polished look that balances perfectly with the snug sweater above."
    },
    {
      "n": "#163·37",
      "text": "Beige sneakers made of soft mesh and smooth rubber panels provide breathability and cushioning for long walks without sacrificing style."
    },
    {
      "n": "#227·20",
      "text": "A bold emerald green belt with a sleek buckle cuts horizontally across your waist to highlight your narrowest point and break up the vertical lines of the outfit."
    },
    {
      "n": "#463·07",
      "text": "This is a structured beige tote bag woven from natural fibers with black leather accents along the handles and base. It offers plenty of space for your day essentials while keeping the look grounded and stylish."
    }
  ]
}
